policies.inbound:











                        application/json


                        @(context.RequestId.ToString())


                        {"web_search_count":null,"total_tokens":null}


                        unavailable

                    @{
                        return new JObject(
                            new JProperty("error", new JObject(
                                new JProperty("code", "invalid_web_search_filters"),
                                new JProperty("message", (string)context.Variables["web-search-validation-error"])
                            ))
                        ).ToString();
                    }



        @{
            var body = context.Request.Body.As<JObject>(preserveContent: true);
            var requiredDomains = new string[] { {organization-blocked-domain-literals} };
            foreach (var item in (JArray)body["tools"])
            {
                var tool = item as JObject;
                if (tool?["type"]?.Type != JTokenType.String || (string)tool["type"] != "web_search")
                {
                    continue;
                }
                var filters = tool["filters"] as JObject;
                if (filters == null)
                {
                    filters = new JObject();
                    tool["filters"] = filters;
                }
                var blocked = filters["blocked_domains"] as JArray;
                if (blocked == null)
                {
                    blocked = new JArray();
                    filters["blocked_domains"] = blocked;
                }
                foreach (var domain in requiredDomains)
                {
                    bool exists = false;
                    foreach (var existing in blocked)
                    {
                        if (string.Equals((string)existing, domain, StringComparison.OrdinalIgnoreCase))
                        {
                            exists = true;
                            break;
                        }
                    }
                    if (!exists)
                    {
                        blocked.Add(domain);
                    }
                }
            }
            return body.ToString(Newtonsoft.Json.Formatting.None);
        }







    @(context.RequestId.ToString())




{backend-routing}

set-variable.value:
@{
                    if (context.Response.StatusCode < 200 || context.Response.StatusCode >= 300)
                    {
                        return -1L;
                    }
                    var contentType = context.Response.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim();
                    if (context.Response.Body == null) { return -1L; }
                    if (!string.Equals(contentType, "application/json", StringComparison.OrdinalIgnoreCase))
                    {
                        return -1L;
                    }
                    try
                    {
                        /* Read the service-reported count only in the non-SSE branch. */
                        var response = context.Response.Body.As<JObject>(preserveContent: true);
                        var toolUsage = response["tool_usage"] as JObject;
                        var webSearch = toolUsage?["web_search"] as JObject;
                        var count = webSearch?["num_requests"];
                        if (count?.Type != JTokenType.Integer) { return -1L; }
                        var total = (long)count;
                        return total >= 0 && total <= 1000000000000000000L ? total : -1L;
                    }
                    catch (Exception)
                    {
                        /* Accounting must not turn an otherwise valid backend response into a 500. */
                        return -1L;
                    }
                }

@{
                    var metrics = new JObject(
                        new JProperty("web_search_count", JValue.CreateNull()),
                        new JProperty("total_tokens", JValue.CreateNull()));
                    var count = (long)context.Variables["web-search-count"];
                    if (count >= 0) { metrics["web_search_count"] = count; }
                    var contentType = context.Response.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim();
                    if (context.Response.StatusCode >= 200 && context.Response.StatusCode < 300
                        && string.Equals(contentType, "application/json", StringComparison.OrdinalIgnoreCase)
                        && context.Response.Body != null)
                    {
                        try
                        {
                            var response = context.Response.Body.As<JObject>(preserveContent: true);
                            var tokens = response?["usage"]?["total_tokens"];
                            if (tokens?.Type == JTokenType.Integer)
                            {
                                var total = (long)tokens;
                                if (total >= 0 && total <= 1000000000000000000L)
                                {
                                    metrics["total_tokens"] = total;
                                }
                            }
                        }
                        catch (Exception) { /* Missing usage must not discard a known search count. */ }
                    }
                    return metrics.ToString(Newtonsoft.Json.Formatting.None);
                }

set-header.value:
@{
                        var metrics = JObject.Parse((string)context.Variables["response-metrics"]);
                        var available = 0;
                        foreach (var metric in metrics.Properties()) {
                            if (metric.Value.Type != JTokenType.Null) { available++; }
                        }
                        return available == 0 ? "unavailable" : (available == metrics.Count ? "reported" : "partial");
                    }
